import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.LiveData
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.launch

class TaskViewModel(application: Application) : AndroidViewModel(application) {

 private val taskDao: TaskDao
 private val repository: TaskRepository
 val allTasks: LiveData<List<Task>>
 val priorityDistribution: LiveData<List<PriorityCount>>

 init {
 val db = TaskDatabase.getDatabase(application)
 taskDao = db.taskDao()
 repository = TaskRepository(taskDao)
 allTasks = repository.allTasks
 priorityDistribution = repository.priorityDistribution
 }

 fun insert(task: Task) = viewModelScope.launch {
 repository.insert(task)
 }

 fun delete(task: Task) = viewModelScope.launch {
 repository.delete(task)
 }

 fun completeTask(taskId: Int) = viewModelScope.launch {
 val task = taskDao.getTaskById(taskId)
 if (task != null) {
 val updatedTask = task.copy(isCompleted = true)
 taskDao.update(updatedTask)
 }
 }

 fun updateTask(task: Task) = viewModelScope.launch {
 taskDao.update(task)
 }
}"},{"role":"assistant","content":[{"type":"text","text":"Now I've found the errors! Let me identify them clearly:

