import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.work.Worker
import androidx.work.WorkerParameters

class NotificationWorker(appContext: Context, workerParams: WorkerParameters) :
 Worker(appContext, workerParams) {

 override fun doWork(): Result {
 val title = inputData.getString("title") ?: "Task Reminder"
 val description = inputData.getString("description") ?: "You have a task due tomorrow!"

 val notificationManager =
 applicationContext.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

 if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
 val channel = NotificationChannel(
 "task_channel",
 "Task Notifications",
 NotificationManager.IMPORTANCE_HIGH
 )
 notificationManager.createNotificationChannel(channel)
 }

 val notification = NotificationCompat.Builder(applicationContext, "task_channel")
 .setSmallIcon(R.drawable.ic_notification) // replace with your icon
 .setContentTitle(title)
 .setContentText(description)
 .setPriority(NotificationCompat.PRIORITY_HIGH)
 .build()

 notificationManager.notify(System.currentTimeMillis().toInt(), notification)

 return Result.success()
 }
}"},{"role":"tool","name":"list_dir","tool_call_id":"toolu_01QkSHDscW4nFWHw9eD7iMkM","content":"Contents of directory:

