 if (originalTask != null) {
 val updatedTask = originalTask.copy(
 title = updatedTitle,
 description = updatedDescription,
 dueDate = updatedDueDate,
 dueTime = updatedDueTime,
 priority = when (updatedPriority.lowercase()) {
