 )
 }
 }
 }
 override fun onRequestPermissionsResult(
 requestCode: Int,
 permissions: Array<out String>,
 grantResults: IntArray
 ) {
 super.onRequestPermissionsResult(requestCode, permissions, grantResults)
 if (requestCode == 1001) {
 if (grantResults.isNotEmpty() && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
 Toast.makeText(requireContext(), "Notifications enabled", Toast.LENGTH_SHORT).show()
 } else {
 Toast.makeText(requireContext(), "Notifications denied", Toast.LENGTH_SHORT).show()
 }
 }
 }
 // WorkManager notification scheduling
 private fun scheduleNotification(task: Task) {
 try {
 val sdf = SimpleDateFormat("dd/MM/yyyy HH:mm", Locale.getDefault())
 val dueDateTime = sdf.parse("${task.dueDate} ${task.dueTime}") ?: return

 val triggerTime = dueDateTime.time - (24 * 60 * 60 * 1000) // 1 day before
 val delay = triggerTime - System.currentTimeMillis()

 if (delay > 0) {
 val data = workDataOf(
 "title" to task.title,
 "description" to task.description
 )

 val workRequest = OneTimeWorkRequestBuilder<NotificationWorker>()
 .setInitialDelay(delay, TimeUnit.MILLISECONDS)
 .setInputData(data)
 .build()

 WorkManager.getInstance(requireContext()).enqueue(workRequest)
 }
 } catch (e: Exception) {
 e.printStackTrace()
 }
 }
