\nimport android.widget.Toast\nimport androidx.appcompat.app.AlertDialog\nimport androidx.core.content.ContextCompat\nimport androidx.fragment.app.Fragment\nimport androidx.lifecycle.ViewModelProvider\nimport com.example.smarttaskmanager.MainActivity3\nimport com.example.smarttaskmanager.NotificationHelper\nimport com.example.smarttaskmanager.NotificationPreferences\nimport com.example.smarttaskmanager.R\nimport com.example.smarttaskmanager.databinding.FragmentSettingBinding\nimport com.google.android.material.floatingactionbutton.FloatingActionButton\n\nclass SettingFragment : Fragment() {\n\n private var _binding: FragmentSettingBinding? = null\n private val binding get() = _binding!!\n\n override fun onCreateView(\n inflater: LayoutInflater,\n container: ViewGroup?,\n savedInstanceState: Bundle?\n ): View {\n val settingViewModel =\n ViewModelProvider(this).get(SettingViewModel::class.java)\n (activity as? MainActivity3)?.findViewById<FloatingActionButton>(R.id.fab)?.hide()\n _binding = FragmentSettingBinding.inflate(inflater, container, false)\n val root: View = binding.root\n\n setupNotificationToggle()\n\n return root\n }\n\n private fun setupNotificationToggle() {\n // Load saved preference\n val isEnabled = NotificationPreferences.areNotificationsEnabled(requireContext())\n binding.notificationSwitch.isChecked = isEnabled\n updateNotificationStatus(isEnabled)\n\n // Handle switch toggle\n binding.notificationSwitch.setOnCheckedChangeListener { _, isChecked ->\n handleNotificationToggle(isChecked)\n }\n\n // Make the entire card clickable\n binding.notificationCard.setOnClickListener {\n binding.notificationSwitch.toggle()\n }\n }\n\n private fun handleNotificationToggle(isEnabled: Boolean) {\n // Check if system permission is granted (Android 13+)\n if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {\n val permissionGranted = ContextCompat.checkSelfPermission(\n requireContext(),\n android.Manifest.permission.POST_NOTIFICATIONS\n ) == PackageManager.PERMISSION_GRANTED\n\n if (isEnabled && !permissionGranted) {\n // User wants to enable but permission not granted\n binding.notificationSwitch.isChecked = false\n showPermissionRequiredDialog()\n return\n }\n }\n\n // Save preference\n NotificationPreferences.setNotificationsEnabled(requireContext(), isEnabled)\n updateNotificationStatus(isEnabled)\n\n // Show feedback\n if (isEnabled) {\n Toast.makeText(\n requireContext(),\n \"Notifications enabled\",\n Toast.LENGTH_SHORT\n ).show()\n // Send test notification\n NotificationHelper.sendTestNotification(requireContext())\n } else {\n Toast.makeText(\n requireContext(),\n \"Notifications disabled\",\n Toast.LENGTH_SHORT\n ).show()\n }\n }\n\n private fun updateNotificationStatus(isEnabled: Boolean) {\n if (isEnabled) {\n binding.notificationStatusText.text = \n \"Notifications are enabled. You'll receive reminders 24 hours before tasks are due.\"\n binding.notificationStatusCard.setCardBackgroundColor(\n ContextCompat.getColor(requireContext(), android.R.color.holo_blue_light)\n )\n } else {\n binding.notificationStatusText.text = \n \"Notifications are disabled. You won't receive task reminders.\"\n binding.notificationStatusCard.setCardBackgroundColor(\n ContextCompat.getColor(requireContext(), android.R.color.holo_orange_light)\n )\n }\n }\n\n private fun showPermissionRequiredDialog() {\n AlertDialog.Builder(requireContext())\n .setTitle(\"Notification Permission Required\")\n .setMessage(\"To enable notifications, you need to grant notification permission in your device settings.\")\n .setPositiveButton(\"Open Settings\") { _, _ ->\n openAppSettings()\n }\n .setNegativeButton(\"Cancel\", null)\n .show()\n }\n\n private fun openAppSettings() {\n try {\n val intent = Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS)\n val uri = Uri.fromParts(\"package\", requireContext().packageName, null)\n intent.data = uri\n startActivity(intent)\n } catch (e: Exception) {\n Toast.makeText(\n requireContext(),\n \"Could not open settings\",\n Toast.LENGTH_SHORT\n ).show()\n }\n }\n\n override fun onResume() {\n super.onResume()\n // Refresh notification state when returning from settings\n val isEnabled = NotificationPreferences.areNotificationsEnabled(requireContext())\n binding.notificationSwitch.isChecked = isEnabled\n updateNotificationStatus(isEnabled)\n }\n\n override fun onDestroyView() {\n super.onDestroyView()\n _binding = null\n }\n}"}"}}]},{"role":"tool","name":"search_replace","tool_call_id":"toolu_01HzeXqJqKdZcbQMeVekTbo9","content":"The file E:\AndroidStudioProjects\SmartTaskManager\app\src\main\java\com\example\smarttaskmanager\ui\setting\SettingFragment.kt has been updated. Here's a relevant snippet of the edited file:

