// Schedule notification 1 day before the due date\n val triggerTime = dueDateTime.time - (24 * 60 * 60 * 1000)\n val delay = triggerTime - System.currentTimeMillis()\n\n if (delay > 0) {\n val data = workDataOf(\n \"title\" to task.title,\n \"description\" to \"Task '${task.title}' is due tomorrow!\"\n )\n\n val workRequest = OneTimeWorkRequestBuilder<NotificationWorker>()\n .setInitialDelay(delay, TimeUnit.MILLISECONDS)\n .setInputData(data)\n .addTag(\"task_${task.title}_${System.currentTimeMillis()}\")\n .build()\n\n WorkManager.getInstance(requireContext()).enqueue(workRequest)\n Toast.makeText(\n requireContext(),\n \"Reminder set for 1 day before due date\",\n Toast.LENGTH_SHORT\n ).show()\n } else {\n Toast.makeText(\n requireContext(),\n \"Due date is too soon to set a reminder\",\n Toast.LENGTH_SHORT\n ).show()\n }\n } catch (e: Exception) {\n e.printStackTrace()\n Toast.makeText(requireContext(), \"Failed to schedule notification\", Toast.LENGTH_SHORT)\n .show()\n }\n }"}"}}]},{"role":"tool","name":"search_replace","tool_call_id":"toolu_01TNkgYCryWXprY6LTsSDWZc","content":"The file E:\AndroidStudioProjects\SmartTaskManager\app\src\main\java\com\example\smarttaskmanager\AddTaskFragment.kt has been updated. Here's a relevant snippet of the edited file:

