import android.content.Intent
import android.os.Bundle
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import com.google.android.material.chip.Chip
import com.google.android.material.chip.ChipGroup
import android.view.View

class EditTaskActivity : AppCompatActivity() {

 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)
 setContentView(R.layout.activity_edit_task)

 setSupportActionBar(findViewById(R.id.editToolbar))
 supportActionBar?.setDisplayHomeAsUpEnabled(false)
 supportActionBar?.title = ""
 findViewById<ImageView>(R.id.backButton).setOnClickListener {
 onBackPressedDispatcher.onBackPressed()
 }

 val titleEditText = findViewById<EditText>(R.id.titleText)
 val descriptionEditText = findViewById<EditText>(R.id.descriptionText)
 val dueDateEditText = findViewById<EditText>(R.id.dueDateText)
 val dueTimeEditText = findViewById<EditText>(R.id.timeText)
 val categoryEditText = findViewById<EditText>(R.id.categorytext)
 val priorityGroup = findViewById<ChipGroup>(R.id.priorityGroup)
 val updateButton = findViewById<Button>(R.id.UpdateTaskButton)

 val originalTitle = intent.getStringExtra("title") ?: ""
 val originalDescription = intent.getStringExtra("description") ?: ""
 val originalDueDate = intent.getStringExtra("dueDate") ?: ""
 val originalDueTime = intent.getStringExtra("dueTime") ?: ""
 val originalPriority = intent.getStringExtra("priority") ?: ""
 val originalCategory = intent.getStringExtra("category") ?: ""


 titleEditText.setText(originalTitle)
 descriptionEditText.setText(originalDescription)
 dueDateEditText.setText(originalDueDate)
 dueTimeEditText.setText(originalDueTime)
 categoryEditText.setText(originalCategory)

 for (i in 0 until priorityGroup.childCount) {
 val chip = priorityGroup.getChildAt(i) as Chip
 if (chip.text.toString().equals(originalPriority, ignoreCase = true)) {
 chip.isChecked = true
 break
 }
 }

 updateButton.setOnClickListener {
 val newTitle = titleEditText.text.toString()
 val newDescription = descriptionEditText.text.toString()
 val newDueDate = dueDateEditText.text.toString()
 val newDueTime = dueTimeEditText.text.toString()
 val newCategory = categoryEditText.text.toString()


 val selectedPriority = if (priorityGroup.checkedChipId != View.NO_ID) {
 val chip = findViewById<Chip>(priorityGroup.checkedChipId)
 chip?.text?.toString() ?: ""
 } else {
 ""
 }


 val resultIntent = Intent().apply {
 putExtra("title", originalTitle)
 putExtra("updatedTitle", newTitle)
 putExtra("updatedDescription", newDescription)
 putExtra("updatedDueDate", newDueDate)
 putExtra("updatedDueTime", newDueTime)
 putExtra("updatedPriority", selectedPriority)
 putExtra("updatedCategory", newCategory)

 }

 setResult(RESULT_OK, resultIntent)
 finish()
 }
 }
}"},{"role":"assistant","content":[{"type":"text","text":"Good! The EditTaskActivity just passes the time as is, so it will work with the new format. Now let me create a comprehensive guide explaining the change:"}],"tool_calls":[{"id":"toolu_01EPSGKb1ifDefsY3vs9Jnxe","type":"function","function":{"name":"write","arguments":"{"file_path": "12_HOUR_FORMAT_UPDATE.md", "contents": "# ✅ Time Format Updated: 24-Hour → 12-Hour (AM/PM)\n\n## What Changed:\n\nYour app now uses **12-HOUR FORMAT with AM/PM** instead of 24-hour format!\n\n---\n\n## Before vs After\n\n### Before (24-Hour Format):\n```\n14:30:00 (2:30 PM)\n08:15:00 (8:15 AM)\n23:45:00 (11:45 PM)\n00:30:00 (12:30 AM)\n```\n\n### After (12-Hour Format with AM/PM):\n```\n02:30:00 PM ✅\n08:15:00 AM ✅\n11:45:00 PM ✅\n12:30:00 AM ✅\n```\n\n---\n\n## What You'll See Now\n\n### 1. Live Clock Display\n**Before:** `14:30:00` \n**Now:** `02:30:00 PM` ✅\n\n### 2. Time Picker\n**Before:** 24-hour clock (0-23) \n**Now:** 12-hour clock with AM/PM selector ✅\n\n### 3. Task Time Storage\n**Before:** `\"14:30:00\"` \n**Now:** `\"02:30:00 PM\"` ✅\n\n### 4. Notifications\n**Before:** Uses 24-hour format for scheduling \n**Now:** Uses 12-hour format with AM/PM ✅\n\n---\n\n## User Experience Changes\n\n### Creating a Task:\n\n**Time Picker NOW shows:**\n```\n┌─────────────────────┐\n│ Select Time │\n│ │\n│ 2 : 30 │\n│ │\n│ ○ AM ● PM │ ← AM/PM selector!\n│ │\n│ [Cancel] [OK] │\n└─────────────────────┘\n```\n\n**Live Clock Display:**\n```\nBefore: 14:30:00\nNow: 02:30:00 PM ✅\n```\n\n---\n\n## Examples\n\n### Morning Tasks:\n```\n6:00 AM → 06:00:00 AM\n8:30 AM → 08:30:00 AM\n11:45 AM → 11:45:00 AM\n```\n\n### Afternoon/Evening Tasks:\n```\n12:00 PM (noon) → 12:00:00 PM\n2:30 PM → 02:30:00 PM\n6:45 PM → 06:45:00 PM\n11:59 PM → 11:59:00 PM\n```\n\n### Midnight/Early Morning:\n```\n12:00 AM (midnight) → 12:00:00 AM\n12:30 AM → 12:30:00 AM\n1:00 AM → 01:00:00 AM\n```\n\n---\n\n## Technical Changes\n\n### Files Modified:\n\n**1. AddTaskFragment.kt**\n\n**Live Clock (Line 40):**\n```kotlin\n// Before:\nSimpleDateFormat(\"HH:mm:ss\") // 24-hour\n\n// After:\nSimpleDateFormat(\"hh:mm:ss a\") // 12-hour with AM/PM ✅\n```\n\n**Time Picker (Line 133):**\n```kotlin\n// Before:\nTimePickerDialog(..., true) // true = 24-hour\n\n// After:\nTimePickerDialog(..., false) // false = 12-hour with AM/PM ✅\n```\n\n**Time Formatting (Line 129):**\n```kotlin\n// After:\nSimpleDateFormat(\"hh:mm:ss a\") // Converts to 12-hour with AM/PM\n```\n\n**Notification Scheduling (Line 224):**\n```kotlin\n// Before:\nSimpleDateFormat(\"dd/MM/yyyy HH:mm:ss\")\n\n// After:\nSimpleDateFormat(\"dd/MM/yyyy hh:mm:ss a\") // With AM/PM ✅\n```\n\n**2. HomeFragment.kt**\n\n**Notification Scheduling (Line 207):**\n```kotlin\n// Before:\nSimpleDateFormat(\"dd/MM/yyyy HH:mm:ss\")\n\n// After:\nSimpleDateFormat(\"dd/MM/yyyy hh:mm:ss a\") // With AM/PM ✅\n```\n\n---\n\n## Format Code Breakdown\n\n### New Format: `hh:mm:ss a`\n\n| Code | Meaning | Example |\n|------|---------|---------|\n| hh | Hour (01-12) | 02 |\n| mm | Minute (00-59) | 30 |\n| ss | Second (00-59) | 45 |\n| a | AM/PM marker | PM |\n\n**Result:** `02:30:45 PM`\n\n---\n\n## How to Use\n\n### Setting a Morning Task (8:30 AM):\n\n1. Click time field\n2. Time picker opens\n3. Set hour: `8`\n4. Set minute: `30`\n5. Select: **AM** ✅\n6. Click OK\n7. See: `08:30:00 AM`\n\n### Setting an Afternoon Task (2:30 PM):\n\n1. Click time field\n2. Time picker opens\n3. Set hour: `2`\n4. Set minute: `30`\n5. Select: **PM** ✅\n6. Click OK\n7. See: `02:30:00 PM`\n\n### Setting a Midnight Task (12:00 AM):\n\n1. Click time field\n2. Time picker opens\n3. Set hour: `12`\n4. Set minute: `00`\n5. Select: **AM** ✅\n6. Click OK\n7. See: `12:00:00 AM`\n\n### Setting a Noon Task (12:00 PM):\n\n1. Click time field\n2. Time picker opens\n3. Set hour: `12`\n4. Set minute: `00`\n5. Select: **PM** ✅\n6. Click OK\n7. See: `12:00:00 PM`\n\n---\n\n## ⚠️ Important Notes\n\n### AM/PM Rules:\n\n**AM (Midnight to Noon):**\n- 12:00 AM = Midnight\n- 1:00 AM to 11:59 AM = Morning\n\n**PM (Noon to Midnight):**\n- 12:00 PM = Noon\n- 1:00 PM to 11:59 PM = Afternoon/Evening\n\n### Time Conversion Chart:\n\n| 24-Hour | 12-Hour |\n|---------|---------|\n| 00:00 | 12:00 AM (midnight) |\n| 01:00 | 01:00 AM |\n| 06:00 | 06:00 AM |\n| 12:00 | 12:00 PM (noon) |\n| 13:00 | 01:00 PM |\n| 14:00 | 02:00 PM |\n| 18:00 | 06:00 PM |\n| 23:00 | 11:00 PM |\n| 23:59 | 11:59 PM |\n\n---\n\n## Testing\n\n### Test 1: Morning Task\n1. Create task\n2. Set time: `8:30 AM`\n3. Live clock shows: `08:30:00 AM` ✅\n4. Database stores: `\"08:30:00 AM\"` ✅\n\n### Test 2: Afternoon Task\n1. Create task\n2. Set time: `2:30 PM`\n3. Live clock shows: `02:30:00 PM` ✅\n4. Database stores: `\"02:30:00 PM\"` ✅\n\n### Test 3: Notification (5 minutes)\n1. Set task for current time + 5 minutes\n2. Example: Now is `02:00 PM`, set `02:05 PM`\n3. Toast: \"Reminder set for 5 minutes from now\"\n4. Wait 5 minutes\n5. Notification appears at `02:05 PM` ✅\n\n---\n\n## ✅ Benefits\n\n1. **Easier to understand** - No mental conversion needed\n2. **More familiar** - Most people use 12-hour format\n3. **Clear AM/PM indication** - No confusion\n4. **Better UX** - User-friendly time picker\n\n---\n\n## Database Compatibility\n\n### Old Tasks (24-Hour Format):\nIf you have existing tasks with 24-hour format, they might not parse correctly.\n\n**Solution:** Recreate tasks or manually update time field.\n\n### New Tasks (12-Hour Format):\nAll new tasks will use 12-hour format with AM/PM automatically.\n\n---\n\n## Summary\n\n**What Changed:**\n- ✅ Live clock: 24-hour → 12-hour with AM/PM\n- ✅ Time picker: 24-hour → 12-hour with AM/PM\n- ✅ Storage: 24-hour → 12-hour with AM/PM\n- ✅ Notifications: 24-hour → 12-hour with AM/PM\n\n**Result:**\n- ✅ Easier to set times\n- ✅ No confusion between AM/PM\n- ✅ More user-friendly\n- ✅ Clear time display\n\n---\n\n## Your App Now Uses 12-Hour Format!\n\n**Example Time Display:**\n```\nMorning: 08:30:00 AM\nNoon: 12:00:00 PM\nAfternoon: 02:30:00 PM\nEvening: 06:45:00 PM\nNight: 11:30:00 PM\nMidnight: 12:00:00 AM\n```\n\n**No more confusion with 14:00, 18:00, 23:00!** ✅\n"}"}}]},{"role":"tool","name":"write","tool_call_id":"toolu_01EPSGKb1ifDefsY3vs9Jnxe","content":"Wrote contents to E:/AndroidStudioProjects/SmartTaskManager/12_HOUR_FORMAT_UPDATE.md.

