import android.content.Intent
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

class MainActivity : AppCompatActivity() {
 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 setContentView(R.layout.activity_main)


 ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
 val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
 v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
 insets
 }


 Handler(Looper.getMainLooper()).postDelayed({
 val intent = Intent(this, MainActivity2::class.java)
 startActivity(intent)
 finish()
 }, 1500)
 }
}"},{"role":"assistant","content":[{"type":"text","text":""}],"tool_calls":[{"id":"toolu_01SbdnpwroZeoytmjVouUPoM","type":"function","function":{"name":"search_replace","arguments":"{"file_path": "app/src/main/java/com/example/smarttaskmanager/MainActivity.kt", "old_string": "package com.example.smarttaskmanager\n\nimport android.content.Intent\nimport android.os.Bundle\nimport android.os.Handler\nimport android.os.Looper\nimport androidx.activity.enableEdgeToEdge\nimport androidx.appcompat.app.AppCompatActivity\nimport androidx.core.view.ViewCompat\nimport androidx.core.view.WindowInsetsCompat\n\nclass MainActivity : AppCompatActivity() {\n override fun onCreate(savedInstanceState: Bundle?) {\n super.onCreate(savedInstanceState)\n enableEdgeToEdge()\n setContentView(R.layout.activity_main)", "new_string": "package com.example.smarttaskmanager\n\nimport android.content.Intent\nimport android.os.Bundle\nimport android.os.Handler\nimport android.os.Looper\nimport androidx.activity.enableEdgeToEdge\nimport androidx.appcompat.app.AppCompatActivity\nimport androidx.appcompat.app.AppCompatDelegate\nimport androidx.core.view.ViewCompat\nimport androidx.core.view.WindowInsetsCompat\n\nclass MainActivity : AppCompatActivity() {\n override fun onCreate(savedInstanceState: Bundle?) {\n super.onCreate(savedInstanceState)\n \n // Force light mode - ignore system dark mode/battery saver\n AppCompatDelegate.setDefaultNightMode(AppCompatDelegate.MODE_NIGHT_NO)\n \n enableEdgeToEdge()\n setContentView(R.layout.activity_main)"}"}}]},{"role":"tool","name":"search_replace","tool_call_id":"toolu_01SbdnpwroZeoytmjVouUPoM","content":"The file E:\AndroidStudioProjects\SmartTaskManager\app\src\main\java\com\example\smarttaskmanager\MainActivity.kt has been updated. Here's a relevant snippet of the edited file:

